import { test, expect } from '@playwright/test';

test.describe('Recorded Test', () => {
  test('should complete recorded Test successfully', async ({ page }) => {
    // Fill "mum" in the From
    await page.locator('#origin').fill('mum')

    // Click the BOM — Mumbai
    await page.getByLabel('BOM — Mumbai').click()

    // Click the Search flights
    await page.locator('#go').click()

    // Click the Add extras for flight AI-887
    await page.getByLabel('Add extras for flight AI-887').click()

    // Click the Add meal to flight AI-887
    await page.getByLabel('Add meal to flight AI-887').click()

    // Click the "Cart" link
    await page.getByLabel('Cart').click()
    await expect.soft(page.locator('#cart-root')).toBeAttached()

    // Click the Increase quantity of MEAL
    await page.getByLabel('Increase quantity of MEAL').click()
    await expect.soft(page.locator('#cart-root')).toBeAttached()

    // Click the Increase quantity of MEAL
    await page.getByLabel('Increase quantity of MEAL').click()
    await expect.soft(page.locator('#cart-root')).toBeAttached()
  });
});
